    "type_of_wind_farm": "Offshore"
  },
  "regulatory_constraints": [
    {
      "type": "Technical",
      "requirement": "For diesel fired engines operating between 0%–20% engine load, the Permittee shall utilize guaranteed emission factors from engine manufacturer’s specifications (or engine specific test data) which indicate a representative emission factor for the lower load intervals for each engine type; or the maximum guaranteed emission factor in units of g/hp-hr (or g/kW-hr) multiplied by the engine-specific load adjustment factors based on known engine mfg. data; or for C3 propulsion engines the maximum guaranteed emission factor in units of g/hp-hr (or g/kW-hr) multiplied by the most representative low load adjustment factors (LLAFs) for the specific pollutant as contained in Table 3.10 of the Port Emissions Inventory Guidance (EPA-420-b-22-011, April 2022). The LLAFs shall be applied separately for each pollutant (and applied to the equation separately for NOx and HC (if HC used as a surrogate for VOC)).",
      "scope": "Diesel fired engines operating between 0%–20% engine load on OCS sources",
      "numerical_value": null,
      "unit": null,
      "source": "Revolution Wind, LLC Outer Continental Shelf Preconstruction Air Permit No. OCS-R1-05 Condition No. VI (A)(5); Port Emissions Inventory Guidance (EPA-420-b-22-011, April 2022)",
      "related_domains": ["air emissions", "engine operation", "environmental compliance"]
    },
    {
      "type": "Technical",
      "requirement": "Emissions of NOx and VOC shall be calculated by taking the product of the brake specific emission factor, the usage in hours (hours per day), the power available (rated power), and the load factor (the power used divided by the power available). For OCS sources, if actual fuel usage data and engine hours are not recorded for that operating day, Permittee shall assume 100% load (full rated hp (kW)) for the emission calculations.",
      "scope": "OCS sources; calculation of NOx and VOC emissions",
      "numerical_value": 100,
      "unit": "percent load",
      "source": "Revolution Wind, LLC Outer Continental Shelf Preconstruction Air Permit No. OCS-R1-05 Condition No. VI (A)(5)",
      "related_domains": ["air emissions", "environmental compliance", "operational monitoring"]
    },
    {
      "type": "Technical",
      "requirement": "For transit emissions from support vessels servicing or associated with the OCS sources, if actual fuel usage data and engine hours are not recorded for that operating day, Permittee can utilize the most representative load factors contained in the Port Emissions Inventory Guidance (EPA-420-b-22-011, April 2022).",
      "scope": "Support vessels servicing or associated with OCS sources",
      "numerical_value": null,
      "unit": null,
      "source": "Port Emissions Inventory Guidance (EPA-420-b-22-011, April 2022)",
